1133:export async function setRate(page: Page, f: { grade: string; pct: string; from?: string; to?: string }): Promise<boolean> {
1134:  await page.getByTestId('rate-form-grade').selectOption(f.grade);
1135:  await page.getByTestId('rate-form-pct').fill(f.pct);
1136:  await setField(page, 'rate-form-from', f.from);
1137:  await setField(page, 'rate-form-to', f.to);
1138:  const r = page.getByTestId(`rate-row-${f.grade}-${f.from ?? 'start'}`);
1139:  const done = async () => (await r.count()) > 0 && await shown(r.getByTestId('rate-pct')) === f.pct
